import { Group, Mesh, PlaneGeometry, Color, DoubleSide } from 'three/webgpu';
import { MeshPhysicalNodeMaterial } from 'three/webgpu';
import { vec3, mix, uv, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const {
    Group: G, Mesh: M, PlaneGeometry: PE, Color: C, DoubleSide: DS,
    RoundedBoxGeometry, Material
  } = {
    Group, Mesh, PlaneGeometry, Color, DoubleSide,
    RoundedBoxGeometry: ctx.THREE.RoundedBoxGeometry,
  };
  const group = new G();

  const palette = ({
    ink: '#16161d', paper: '#e8ecf2', accent: '#ff2a38', surface: '#0b0b10'
  });
  (Object.assign(palette, config.colors || {}));

  group.userData.handlers = {};

  // Backdrop plane with engineered gradient surface -> ink
  const backdropMat = new MeshPhysicalNodeMaterial({
    side: DoubleSide,
    roughness: 0.75,
    metalness: 0.05,
    colorNode: mix(
      vec3().rgb.fromHex(palette.surface),
      vec3().rgb.fromHex(palette.ink),
      smoothstep(0, 1, uv().y)
    ),
  });
  const backdrop = new M(new PlaneGeometry(7, 6), backdropMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);

  // Card panel — machined surface
  const cardGeo = new (ctx.THREE.RoundedBoxGeometry ? ctx.THREE.RoundedBoxGeometry : PlaneGeometry)(
    1.4, 1.7, 0.12, 4, 0.08
  );
  const cardMat = new MeshPhysicalNodeMaterial({
    color: new Color(palette.ink),
    metalness: 0.5,
    roughness: 0.55,
    clearcoat: 0.2,
    clearcoatRoughness: 0.45,
  });
  const card = new M(cardGeo, cardMat);
  card.position.set(0, 0, 0.08);
  group.add(card);

  // Accent edge — thin emissive strip along right side
  const edgeMat = new MeshPhysicalNodeMaterial({
    color: new Color(palette.accent),
    emissive: new Color(palette.accent),
    emissiveIntensity: 1.4,
    roughness: 0.6,
    metalness: 0.3,
  });
  const edgeGeo = new PlaneGeometry(0.04, 1.2);
  const accentEdge = new M(edgeGeo, edgeMat);
  accentEdge.position.set(0.68, 0, 0.18);
  group.add(accentEdge);

  // Gear GLB subject loaded through loader, cached
  let gltfScene = null;
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      gltfScene = gltf.scene;
      gltfScene.traverse((o) => {
        if (o.isMesh) {
          if (!o.material || !o.material.metalness) {
            o.material = new MeshPhysicalNodeMaterial({
              color: new Color(palette.paper),
              metalness: 0.5,
              roughness: 0.5,
              clearcoat: 0.15,
            });
          }
        }
      });
      // gear sits atop the card, machined metal feel
      gltfScene.position.set(0, 0.18, 0.32);
      gltfScene.scale.setScalar(0.5);
      card.add(gltfScene);
    });
  }

  // Contact shadow plane under the card
  const shadowMat = new MeshPhysicalNodeMaterial({
    transparent: true,
    opacity: 0.5,
    roughness: 1,
    metalness: 0,
    color: new Color(0x000000),
  });
  const shadowGeo = new PlaneGeometry(1.9, 1.2);
  const shadow = new M(shadowGeo, shadowMat);
  shadow.position.set(0, -0.85, -0.05);
  shadow.rotation.set(-0.12, 0, 0);
  group.add(shadow);

  // Lights node-local (scene provides ambient 0.6 + key 1.2)
  const rim = new ctx.THREE.PointLight(new Color(palette.accent), 0.9, 6);
  rim.position.set(1.4, 0.4, 1.5);
  group.add(rim);
  const back = new ctx.THREE.PointLight(new Color(palette.paper), 0.6, 6);
  back.position.set(-1.2, -0.6, -1.2);
  group.add(back);

  // Cinematic primitive: parallax-scroll on scroll trigger
  const primitiveResults = [];
  const primitives = config.cinematicPrimitives || [];
  for (const p of primitives) {
    if (ctx.primitives && ctx.primitives[p.name]) {
      const r = ctx.primitives[p.name](card, p.params || {});
      if (r) primitiveResults.push(r);
    }
  }

  // Interaction handlers — stored on userData.handlers
  const tlDefaults = gsap.timeline({ paused: true });
  gsap.to(card.position, { y: 0.15, duration: 0.7, ease: 'power3.out', overwrite: true });

  const hoverTl = gsap.timeline({ paused: true });
  hoverTl.to(card.position, { y: 0.15, duration: 0.7, ease: 'power3.out' }, 0)
    .to(accentEdge.material.emissiveIntensity, { 1: '', duration: 0.4, ease: 'power2.out' }, 0);

  const settleTl = gsap.timeline({ paused: true });
  settleTl.to(card.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.5, ease: 'power3.out' })
    .to(card.scale, { x: 1, y: 1, z: 1, duration: 0.4, ease: 'power4.out' });

  group.userData.handlers.onpointerenter = () => {
    gsap.killTweensOf(card.position);
    gsap.to(card.position, { y: 0.15, duration: 0.7, ease: 'power3.out' });
    gsap.to(accentEdge.material, { emissiveIntensity: 1.8, duration: 0.4, ease: 'power2.out' });
  };
  group.userData.handlers.onpointerleave = () => {
    gsap.killTweensOf(card.position);
    gsap.to(card.position, { y: 0, duration: 0.6, ease: 'power3.out' });
    gsap.to(accentEdge.material, { emissiveIntensity: 1.4, duration: 0.4, ease: 'power2.out' });
  };
  group.userData.handlers.onpointerdown = () => {
    gsap.killTweensOf(card.scale);
    gsap.to(card.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out' });
  };
  group.userData.handlers.onpointerup = () => {
    gsap.killTweensOf(card.scale);
    settleTl.restart();
    ctx.emit('hub-home.select', { source: 'stat-tile' });
  };
  group.userData.handlers.onpointermove = () => {};

  // Entrance settle animation
  card.scale.setScalar(0.97);
  gsap.to(card.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.5, ease: 'power3.out', delay: 0.2 });
  gsap.to(card.scale, { x: 1, y: 1, z: 1, duration: 0.4, ease: 'power4.out', delay: 0.7 });

  // Cleanup
  group.userData.cleanup = () => {
    gsap.killTweensOf(card.position);
    gsap.killTweensOf(card.scale);
    gsap.killTweensOf(accentEdge.material);
    for (const r of primitiveResults) {
      try { r.cleanup && r.cleanup(); } catch (e) {}
    }
    backdropGeoDispose(backdrop, card, accentEdge, shadow);
    cardMat.dispose(); edgeMat.dispose(); shadowMat.dispose(); backdropMat.dispose();
    if (cardGeo.dispose) cardGeo.dispose();
    if (edgeGeo.dispose) edgeGeo.dispose();
    if (shadowGeo.dispose) shadowGeo.dispose();
    if (backdropGeoDispose && backdrop.geometry && backdrop.geometry.dispose) backdrop.geometry.dispose();
  };

  function backdropGeoDispose() {
    if (gltfScene && gltfScene.traverse) {
      gltfScene.traverse((o) => {
        if (o.geometry && o.geometry.dispose) o.geometry.dispose();
        if (o.material && o.material.dispose) o.material.dispose();
      });
    }
  }

  return group;
}
